#requires -Version 5.1
[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$Stage3V5RunRoot,
    [string]$RepoRoot = '',
    [string]$ArchiveRoot = 'D:\CFA-bulk\source\gdelt-gkg-q2-2025',
    [string]$OutputRoot = '',
    [switch]$SelfTest
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
function Write-Utf8NoBom{param([string]$Path,[string]$Content);$p=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $p -PathType Container)){New-Item -ItemType Directory -Path $p -Force|Out-Null};[IO.File]::WriteAllText($Path,$Content,(New-Object Text.UTF8Encoding($false)))}
function Get-Sha{param([string]$Path);return(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Invoke-Child{param([string]$Path,[hashtable]$Args);$global:LASTEXITCODE=$null;& $Path @Args;$code=if($null-eq$LASTEXITCODE){0}else{[int]$LASTEXITCODE};$global:LASTEXITCODE=0;if($code-ne0){throw "Child script failed with exit ${code}: $Path"}}
function SelfTest{foreach($n in @('Apply-CfaStage3NewsMatchingV6.ps1','Prepare-CfaStage3V6SampleReview.ps1','Summarize-CfaStage3NewsByAsset.ps1')){if(-not(Test-Path -LiteralPath (Join-Path $PSScriptRoot $n)-PathType Leaf)){throw "Missing V6 component: $n"}};$tmp=Join-Path ([IO.Path]::GetTempPath()) ('cfa-v6-probe-'+[guid]::NewGuid().ToString('N')+'.ps1');try{[IO.File]::WriteAllText($tmp,"param([string]`$A)`nif(`$A-ne'alpha'){exit 9}`nexit 0`n",(New-Object Text.UTF8Encoding($false)));Invoke-Child $tmp @{A='alpha'}}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue};Write-Host 'SELF-TEST: PASS'}
if($SelfTest){try{SelfTest;exit 0}catch{Write-Host 'SELF-TEST: FAIL';Write-Host $_.Exception.Message;exit 1}}
try{if([string]::IsNullOrWhiteSpace($RepoRoot)){$RepoRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))};$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).ProviderPath;$ArchiveRoot=(Resolve-Path -LiteralPath $ArchiveRoot).ProviderPath;$Stage3V5RunRoot=(Resolve-Path -LiteralPath $Stage3V5RunRoot).ProviderPath;if([string]::IsNullOrWhiteSpace($OutputRoot)){$base='D:\CFA-bulk\analysis\stage3-news-matching';if(-not(Test-Path -LiteralPath $base -PathType Container)){throw "Default analysis root missing: $base"};$OutputRoot=Join-Path $base ((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss')+'-v6-finalization-'+[guid]::NewGuid().ToString('N').Substring(0,8))};if(Test-Path -LiteralPath $OutputRoot){if(@(Get-ChildItem -LiteralPath $OutputRoot -Force -ErrorAction SilentlyContinue).Count-gt0){throw "OutputRoot must be empty: $OutputRoot"}}else{New-Item -ItemType Directory -Path $OutputRoot -Force|Out-Null};$OutputRoot=(Resolve-Path -LiteralPath $OutputRoot).ProviderPath;Write-Host("Selected V5 parent: {0}"-f$Stage3V5RunRoot);Write-Host("V6 finalization evidence root: {0}"-f$OutputRoot);$v6Root=Join-Path $OutputRoot 'v6';$reviewRoot=Join-Path $OutputRoot 'review';New-Item -ItemType Directory -Path $reviewRoot -Force|Out-Null;$apply=Join-Path $PSScriptRoot 'Apply-CfaStage3NewsMatchingV6.ps1';Invoke-Child $apply @{Stage3V5RunRoot=$Stage3V5RunRoot;RepoRoot=$RepoRoot;ArchiveRoot=$ArchiveRoot;OutputRoot=$v6Root};$summaryPath=Join-Path $v6Root 'stage3-match-summary.json';$v6=Get-Content -LiteralPath $summaryPath -Raw|ConvertFrom-Json;if([string]$v6.run_status-ne'PASS'-or[string]$v6.matching_contract-ne'CANDIDATE_V6'-or[string]$v6.gates.'CFA-S3F-021'-ne'PASS'-or[string]$v6.gates.'CFA-S3F-022'-ne'PASS'){throw'V6 correction gates did not PASS.'};$reviewScript=Join-Path $PSScriptRoot 'Prepare-CfaStage3V6SampleReview.ps1';Invoke-Child $reviewScript @{Stage3V6RunRoot=$v6Root;OutputRoot=$reviewRoot};$reviewSummary=@(Get-ChildItem -LiteralPath $reviewRoot -Recurse -File -Filter 'stage3-v6-bounded-sample-review-summary.json'|Sort-Object LastWriteTimeUtc -Descending|Select-Object -First 1);if($reviewSummary.Count-ne1){throw'V6 review summary missing.'};$r=Get-Content -LiteralPath $reviewSummary[0].FullName -Raw|ConvertFrom-Json;if([string]$r.status-ne'PASS'){throw'V6 review preparation did not PASS.'};$count=Join-Path $PSScriptRoot 'Summarize-CfaStage3NewsByAsset.ps1';Invoke-Child $count @{Stage3RunRoot=$v6Root};$counts=Join-Path $v6Root 'stage3-news-counts-by-asset.csv';$reviewCsv=[string]$r.output_review_csv;$receipt=[ordered]@{status='VALIDATION_CANDIDATE';stage='CFA_STAGE_3';matching_contract='CANDIDATE_V6';parent_v5_run=$Stage3V5RunRoot;parent_v5_summary_sha256=(Get-Sha (Join-Path $Stage3V5RunRoot 'stage3-match-summary.json'));v6_run_root=$v6Root;v6_summary_sha256=(Get-Sha $summaryPath);review_summary=$reviewSummary[0].FullName;review_summary_sha256=(Get-Sha $reviewSummary[0].FullName);review_csv=$reviewCsv;review_csv_sha256=(Get-Sha $reviewCsv);news_counts_csv=$counts;news_counts_sha256=(Get-Sha $counts);gates=[ordered]@{'CFA-S3F-008'='FAIL';'CFA-S3F-014'='FAIL';'CFA-S3F-019'='FAIL';'CFA-S3F-020'='BLOCKED';'CFA-S3F-021'='PASS';'CFA-S3F-022'='PASS';'CFA-S3F-023'='UNVERIFIED';'CFA-S3F-024'='BLOCKED';'CFA-S3-005'='UNVERIFIED';'CFA-S3-006'='BLOCKED'};next_action='Directly review every row in review_csv. Freeze only if no obvious false positive or false negative remains.'};$receiptPath=Join-Path $OutputRoot 'stage3-v6-finalization-candidate.json';Write-Utf8NoBom $receiptPath (($receipt|ConvertTo-Json -Depth 10)+[Environment]::NewLine);Write-Host '';Write-Host 'CFA STAGE 3 V6 FINALIZATION: VALIDATION CANDIDATE';Write-Host 'CFA-S3F-019 historical V5 semantic review: FAIL (preserved)';Write-Host 'CFA-S3F-021 V6 local-market rule: PASS';Write-Host 'CFA-S3F-022 corrected V6 candidate: PASS';Write-Host 'CFA-S3F-023 direct V6 semantic review: UNVERIFIED';Write-Host 'CFA-S3-006 freeze news matching: BLOCKED';Write-Host("Review CSV: {0}"-f$reviewCsv);Write-Host("Candidate receipt: {0}"-f$receiptPath);exit 0}catch{Write-Host '';Write-Host 'CFA STAGE 3 V6 FINALIZATION: FAIL';Write-Host $_.Exception.Message;if($_.ScriptStackTrace){Write-Host $_.ScriptStackTrace};exit 1}
